method:
Hash: b3sum 1.8.7 (nixpkgs#b3sum, run via nix shell), an independent BLAKE3 implementation; not this crate's blake3 dependency. For each ULID text U: printf %s "$U" | b3sum --no-names. Base-32 step: node v24, below. Bit order: the first 5 bytes of the digest as 40 bits, most significant bit first, five bits per character, alphabet 0123456789abcdefghjkmnpqrstvwxyz. Initials were derived by hand from the RFC rule.
--- shell ---
for u in 01K6YQ2A4D8F1H3J5K7M9N0P2Q 01M4CC0VMR8HSPZXQ1WX41GWVK 00000000000000000000000000 7ZZZZZZZZZZZZZZZZZZZZZZZZZ 01K7F6H9J2N4Q6S8V0X2Z4B6DE 01ARZ3NDEKTSV4RRFFQ69G5FAV 01HZZ0000000000000000ABCDE 3VZ9Y8X7W6T5S4R3Q2P1N0M9KJ; do
  printf '%s %s\n' "$u" "$(printf %s "$u" | b3sum --no-names)"
done
--- node ---
const A = "0123456789abcdefghjkmnpqrstvwxyz";
for (const l of require("fs").readFileSync(process.argv[2], "utf8").trim().split("\n")) {
  const [u, h] = l.split(" ");
  const bits = [...Buffer.from(h, "hex").subarray(0, 5)].map(b => b.toString(2).padStart(8, "0")).join("");
  const code = n => Array.from({ length: n }, (_, i) => A[parseInt(bits.slice(i * 5, i * 5 + 5), 2)]).join("");
  console.log(JSON.stringify({ ulid: u, codes: { 5: code(5), 6: code(6), 7: code(7), 8: code(8) } }));
}
